114:  * Gets the specific error corresponding to SOCKET_ERROR
115:  * @param aString the function that was being used when the error occurred
116:  * @param sock the socket on which the error occurred
117:  * @return the specific TCP error code
118:  */
119: int Socket_error(char* aString, SOCKET sock)
120: {
121: 	int err;
122: 
123: #if defined(_WIN32)
124: 	err = WSAGetLastError();
125: #else
126: 	err = errno;
127: #endif
128: 	if (err != EINTR && err != EAGAIN && err != EINPROGRESS && err != EWOULDBLOCK)
129: 	{
130: 		if (strcmp(aString, "shutdown") != 0 || (err != ENOTCONN && err != ECONNRESET))
131: 			Log(LOG_PROTOCOL, -1, "Socket error %s(%d) in %s for socket %d", strerror(err), err, aString, sock);
132: 	}
133: 	return err;
