165: int socketpair(int domain, int type, int protocol, SOCKET socks[2])
166: {
167:     SOCKET listener = INVALID_SOCKET;
168:     SOCKET client = INVALID_SOCKET;
169:     SOCKET server = INVALID_SOCKET;
170:     struct sockaddr_in addr;
171:     int addr_len = sizeof(addr);
172:     int reuse = 1;
173: 
174:     /* Only support AF_INET (or AF_UNIX which we map to AF_INET) */
175:     if (domain != AF_INET && domain != AF_UNIX) {
176:         errno = EAFNOSUPPORT;
177:         return -1;
178:     }
179: 
180:     /* Only support SOCK_STREAM */
181:     if (type != SOCK_STREAM) {
182:         errno = EPROTONOSUPPORT;
183:         return -1;
184:     }
185: 
186:     socks[0] = socks[1] = INVALID_SOCKET;
187: 
188:     /* Create listener socket on loopback */
189:     listener = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
190:     if (listener == INVALID_SOCKET) {
191:         goto error;
192:     }
193: 
194:     /* Allow rapid reuse of the address */
195:     setsockopt(listener, SOL_SOCKET, SO_REUSEADDR,
196:                (const char*)&reuse, sizeof(reuse));
197: 
198:     /* Bind to loopback with OS-assigned port */
199:     memset(&addr, 0, sizeof(addr));
200:     addr.sin_family = AF_INET;
201:     addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
202:     addr.sin_port = 0;  /* Let OS choose port */
203: 
204:     if (bind(listener, (struct sockaddr*)&addr, sizeof(addr)) == SOCKET_ERROR) {
205:         goto error;
206:     }
207: 
208:     /* Get the actual address (with port assigned by OS) */
209:     if (getsockname(listener, (struct sockaddr*)&addr, &addr_len) == SOCKET_ERROR) {
210:         goto error;
211:     }
212: 
213:     /* Listen for connection */
214:     if (listen(listener, 1) == SOCKET_ERROR) {
215:         goto error;
216:     }
217: 
218:     /* Create client socket */
219:     client = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
220:     if (client == INVALID_SOCKET) {
221:         goto error;
222:     }
223: 
224:     /* Connect to listener */
225:     if (connect(client, (struct sockaddr*)&addr, sizeof(addr)) == SOCKET_ERROR) {
226:         goto error;
227:     }
228: 
229:     /* Accept connection */
230:     server = accept(listener, NULL, NULL);
231:     if (server == INVALID_SOCKET) {
232:         goto error;
233:     }
234: 
235:     /* Close listener - no longer needed */
236:     closesocket(listener);
237: 
238:     /* Return the pair */
239:     socks[0] = client;
240:     socks[1] = server;
241: 
242:     return 0;
