438: /**
439:  * Add a socket to the list of socket to check with select
440:  * @param newSd the new socket to add
441:  * @return 0 if successful
442:  */
443: int Socket_addSocket(SOCKET newSd)
444: {
445: 	int rc = 0;
446: 
447: 	FUNC_ENTRY;
448: 	Paho_thread_lock_mutex(socket_mutex);
449: 	mod_s.nfds++;
450: 	if (mod_s.fds_read)
451: 	{
452: 		void* newPtr = realloc(mod_s.fds_read, mod_s.nfds * sizeof(mod_s.fds_read[0]));
453: 		if (newPtr == NULL)
454: 		{
455: 			free(mod_s.fds_read);
456: 			mod_s.fds_read = NULL;
457: 		}
458: 		else
459: 		{
460: 			mod_s.fds_read = newPtr;
461: 		}
462: 	}
463: 	else
464: 		mod_s.fds_read = malloc(mod_s.nfds * sizeof(mod_s.fds_read[0]));
465: 	if (!mod_s.fds_read)
466: 	{
467: 		rc = PAHO_MEMORY_ERROR;
468: 		goto exit;
469: 	}
470: 	if (mod_s.fds_write)
471: 	{
472: 		void* newPtr = realloc(mod_s.fds_write, mod_s.nfds * sizeof(mod_s.fds_write[0]));
473: 		if (newPtr == NULL)
474: 		{
475: 			free(mod_s.fds_write);
476: 			mod_s.fds_write = NULL;
477: 		}
478: 		else
479: 		{
480: 			mod_s.fds_write = newPtr;
481: 		}
482: 	}
483: 	else
484: 		mod_s.fds_write = malloc(mod_s.nfds * sizeof(mod_s.fds_write[0]));
485: 	if (!mod_s.fds_write)
486: 	{
487: 		rc = PAHO_MEMORY_ERROR;
488: 		goto exit;
489: 	}
490: 
491: 	mod_s.fds_read[mod_s.nfds - 1].fd = newSd;
492: 	mod_s.fds_write[mod_s.nfds - 1].fd = newSd;
493: #if defined(_WIN32)
494: 	mod_s.fds_read[mod_s.nfds - 1].events = POLLIN;
495: 	mod_s.fds_write[mod_s.nfds - 1].events = POLLOUT;
496: #else
497: 	mod_s.fds_read[mod_s.nfds - 1].events = POLLIN | POLLNVAL;
498: 	mod_s.fds_write[mod_s.nfds - 1].events = POLLOUT;
499: #endif
500: 
501: 	/* sort the poll fds array by socket number */
502: 	qsort(mod_s.fds_read, (size_t)mod_s.nfds, sizeof(mod_s.fds_read[0]), cmpfds);
503: 	qsort(mod_s.fds_write, (size_t)mod_s.nfds, sizeof(mod_s.fds_write[0]), cmpfds);
504: 
505: 	rc = Socket_setnonblocking(newSd);
506: 	if (rc == SOCKET_ERROR)
507: 		Log(LOG_ERROR, -1, "addSocket: setnonblocking");
508: 
509: exit:
510: 	Paho_thread_unlock_mutex(socket_mutex);
511: 	FUNC_EXIT_RC(rc);
512: 	return rc;
513: }
514: #endif
