518: /**
519:  * Don't accept work from a client unless it is accepting work back, i.e. its socket is writeable
520:  * this seems like a reasonable form of flow control, and practically, seems to work.
521:  * @param socket the socket to check
522:  * @param read_set the socket read set (see select doc)
523:  * @param write_set the socket write set (see select doc)
524:  * @return boolean - is the socket ready to go?
525:  */
526: int isReady(int socket, fd_set* read_set, fd_set* write_set)
527: {
528: 	int rc = 1;
529: 
530: 	FUNC_ENTRY;
531: 	if  (ListFindItem(mod_s.connect_pending, &socket, intcompare) && FD_ISSET(socket, write_set))
532: 		ListRemoveItem(mod_s.connect_pending, &socket, intcompare);
533: 	else
534: 		rc = FD_ISSET(socket, read_set) && FD_ISSET(socket, write_set) && Socket_noPendingWrites(socket);
535: 	FUNC_EXIT_RC(rc);
536: 	return rc;
537: }
538: #else
539: /**
540:  * Don't accept work from a client unless it is accepting work back, i.e. its socket is writeable
541:  * this seems like a reasonable form of flow control, and practically, seems to work.
542:  * @param index the socket index to check
543:  * @return boolean - is the socket ready to go?
544:  */
545: int isReady(int index)
546: {
547: 	int rc = 1;
548: 	SOCKET* socket = &mod_s.saved.fds_write[index].fd;
549: 
550: 	FUNC_ENTRY;
551: 
552: 	if (*socket == sockfd[0]) /* don't return the interrupting socket */
553: 		rc = 0;
554: 	else if ((mod_s.saved.fds_read[index].revents & POLLHUP) || (mod_s.saved.fds_read[index].revents & POLLNVAL))
555: 		; /* signal work to be done if there is an error on the socket */
556: 	else if  (ListFindItem(mod_s.connect_pending, socket, intcompare) &&
557: 			(mod_s.saved.fds_write[index].revents & POLLOUT))
558: 		ListRemoveItem(mod_s.connect_pending, socket, intcompare);
559: 	else
560: 		rc = (mod_s.saved.fds_read[index].revents & POLLIN) &&
561: 			 (mod_s.saved.fds_write[index].revents & POLLOUT) &&
562: 			 Socket_noPendingWrites(*socket);
563: 
564: 	FUNC_EXIT_RC(rc);
565: 	return rc;
566: }
567: #endif
