592: /**
593:  *  Returns the next socket ready for communications as indicated by select
594:  *  @param more_work flag to indicate more work is waiting, and thus a timeout value of 0 should
595:  *  be used for the select
596:  *  @param timeout the timeout to be used for the select, unless overridden
597:  *  @param rc a value other than 0 indicates an error of the returned socket
598:  *  @return the socket next ready, or 0 if none is ready
599:  */
600: SOCKET Socket_getReadySocket(int more_work, int timeout, mutex_type mutex, int* rc)
601: {
602: 	SOCKET sock = 0;
603: 	*rc = 0;
604: 	int timeout_ms = 1000;
605: 
606: 	FUNC_ENTRY;
607: 	Paho_thread_lock_mutex(mutex);
608: 	if (mod_s.clientsds->count == 0)
609: 		goto exit;
610: 		
611: 	if (more_work)
612: 		timeout_ms = 0;
613: 	else if (timeout >= 0)
614: 		timeout_ms = timeout;
615: 
616: 	while (mod_s.cur_clientsds != NULL)
617: 	{
618: 		if (isReady(*((int*)(mod_s.cur_clientsds->content)), &(mod_s.rset), &wset))
619: 			break;
620: 		ListNextElement(mod_s.clientsds, &mod_s.cur_clientsds);
621: 	}
622: 
623: 	if (mod_s.cur_clientsds == NULL)
624: 	{
625: 		static struct timeval zero = {0L, 0L}; /* 0 seconds */
626: 		int rc1, maxfdp1_saved;
627: 		fd_set pwset;
628: 		struct timeval timeout_tv = {0L, 0L};
629: 
630: 		if (timeout_ms > 0L)
631: 		{
632: 			timeout_tv.tv_sec = timeout_ms / 1000;
633: 			timeout_tv.tv_usec = (timeout_ms % 1000) * 1000; /* this field is microseconds! */
634: 		}
635: 
636: 		memcpy((void*)&(mod_s.rset), (void*)&(mod_s.rset_saved), sizeof(mod_s.rset));
637: 		memcpy((void*)&(pwset), (void*)&(mod_s.pending_wset), sizeof(pwset));
638: 		maxfdp1_saved = mod_s.maxfdp1;
639: 		
640: 		if (maxfdp1_saved == 0)
641: 		{
642: 			sock = 0;
643: 			goto exit; /* no work to do */
644: 		}
645: 		/* Prevent performance issue by unlocking the socket_mutex while waiting for a ready socket. */
646: 		Paho_thread_unlock_mutex(mutex);
647: 		*rc = select(maxfdp1_saved, &(mod_s.rset), &pwset, NULL, &timeout_tv);
648: 		Paho_thread_lock_mutex(mutex);
649: 		if (*rc == SOCKET_ERROR)
650: 		{
651: 			Socket_error("read select", 0);
652: 			goto exit;
653: 		}
654: 		Log(TRACE_MAX, -1, "Return code %d from read select", *rc);
655: 
656: 		if (Socket_continueWrites(&pwset, &sock, mutex) == SOCKET_ERROR)
657: 		{
658: 			*rc = SOCKET_ERROR;
659: 			goto exit;
660: 		}
661: 
662: 		memcpy((void*)&wset, (void*)&(mod_s.rset_saved), sizeof(wset));
663: 		if ((rc1 = select(mod_s.maxfdp1, NULL, &(wset), NULL, &zero)) == SOCKET_ERROR)
664: 		{
665: 			Socket_error("write select", 0);
666: 			*rc = rc1;
667: 			goto exit;
668: 		}
669: 		Log(TRACE_MAX, -1, "Return code %d from write select", rc1);
670: 
671: 		if (*rc == 0 && rc1 == 0)
672: 		{
673: 			sock = 0;
674: 			goto exit; /* no work to do */
675: 		}
676: 
677: 		mod_s.cur_clientsds = mod_s.clientsds->first;
678: 		while (mod_s.cur_clientsds != NULL)
679: 		{
680: 			int cursock = *((int*)(mod_s.cur_clientsds->content));
681: 			if (isReady(cursock, &(mod_s.rset), &wset))
682: 				break;
683: 			ListNextElement(mod_s.clientsds, &mod_s.cur_clientsds);
684: 		}
685: 	}
686: 
687: 	*rc = 0;
688: 	if (mod_s.cur_clientsds == NULL)
689: 		sock = 0;
690: 	else
691: 	{
692: 		sock = *((int*)(mod_s.cur_clientsds->content));
693: 		ListNextElement(mod_s.clientsds, &mod_s.cur_clientsds);
694: 	}
695: exit:
696: 	Paho_thread_unlock_mutex(mutex);
697: 	FUNC_EXIT_RC(sock);
698: 	return sock;
699: } /* end getReadySocket */
700: #else
701: /**
702:  *  Returns the next socket ready for communications as indicated by select
703:  *  @param more_work flag to indicate more work is waiting, and thus a timeout value of 0 should
704:  *  be used for the select
705:  *  @param timeout the timeout to be used in ms
706:  *  @param rc a value other than 0 indicates an error of the returned socket
707:  *  @return the socket next ready, or 0 if none is ready
708:  */
709: SOCKET Socket_getReadySocket(int more_work, int timeout, mutex_type mutex, int* rc, int* interrupted)
710: {
711: 	SOCKET sock = 0;
712: 	*rc = 0;
713: 	int timeout_ms = 1000;
714: 
715: 	FUNC_ENTRY;
716: 	Paho_thread_lock_mutex(mutex);
717: 	if (mod_s.nfds == 0 && mod_s.saved.nfds == 0)
718: 		goto exit;
719: 
720: 	if (more_work)
721: 		timeout_ms = 0;
722: 	else if (timeout >= 0)
723: 		timeout_ms = timeout;
724: 
725: 	while (mod_s.saved.cur_fd != -1)
726: 	{
727: 		if (isReady(mod_s.saved.cur_fd))
728: 			break;
729: 		mod_s.saved.cur_fd = (mod_s.saved.cur_fd == mod_s.saved.nfds - 1) ? -1 : mod_s.saved.cur_fd + 1;
730: 	}
731: 
732: 	if (mod_s.saved.cur_fd == -1)
733: 	{
734: 		int rc1 = 0;
735: 
736: 		if (mod_s.nfds != mod_s.saved.nfds)
737: 		{
738: 			mod_s.saved.nfds = mod_s.nfds;
739: 			if (mod_s.nfds == 0)
740: 			{
741: 				if (mod_s.saved.fds_read)
742: 				{
743: 					free(mod_s.saved.fds_read);
744: 					mod_s.saved.fds_read = NULL;
745: 				}
746: 			}
747: 			else if (mod_s.saved.fds_read)
748: 			{
749: 				void* newPtr = realloc(mod_s.saved.fds_read, mod_s.nfds * sizeof(struct pollfd));
750: 				if (newPtr == NULL)
751: 				{
752: 					free(mod_s.saved.fds_read);
753: 					mod_s.saved.fds_read = NULL;
754: 				}
755: 				else
756: 				{
757: 					mod_s.saved.fds_read = newPtr;
758: 				}
759: 			}
760: 			else
761: 				mod_s.saved.fds_read = malloc(mod_s.nfds * sizeof(struct pollfd));
762: 
763: 			if (mod_s.nfds == 0)
764: 			{
765: 				if (mod_s.saved.fds_write)
766: 				{
767: 					free(mod_s.saved.fds_write);
768: 					mod_s.saved.fds_write = NULL;
769: 				}
770: 			}
771: 			else if (mod_s.saved.fds_write)
772: 			{
773: 				void* newPtr = realloc(mod_s.saved.fds_write, mod_s.nfds * sizeof(struct pollfd));
774: 				if (newPtr == NULL)
775: 				{
776: 					free(mod_s.saved.fds_write);
777: 					mod_s.saved.fds_write = NULL;
778: 				}
779: 				else
780: 				{
781: 					mod_s.saved.fds_write = newPtr;
782: 				}
783: 			}
784: 			else
785: 				mod_s.saved.fds_write = malloc(mod_s.nfds * sizeof(struct pollfd));
786: 		}
787: 		if (mod_s.fds_read == NULL)
788: 			mod_s.saved.fds_read = NULL;
789: 		else
790: 			memcpy(mod_s.saved.fds_read, mod_s.fds_read, mod_s.nfds * sizeof(struct pollfd));
791: 		if (mod_s.fds_write == NULL)
792: 			mod_s.saved.fds_write = NULL;
793: 		else
794: 			memcpy(mod_s.saved.fds_write, mod_s.fds_write, mod_s.nfds * sizeof(struct pollfd));
795: 
796: 		if (mod_s.saved.nfds == 0)
797: 		{
798: 			sock = 0;
799: 			goto exit; /* no work to do */
800: 		}
801: 
802: 		/* Check pending write set for writeable sockets */
803: 		rc1 = poll(mod_s.saved.fds_write, mod_s.saved.nfds, 0);
804: 		if (rc1 > 0 && Socket_continueWrites(&sock, mutex) == SOCKET_ERROR)
805: 		{
806: 			*rc = SOCKET_ERROR;
807: 			goto exit;
808: 		}
809: 		/* if there is a writeable socket in the connecting state then set the timeout for the
810: 		 * next poll to 0 or a low value, so we can handle the connect immediately */
811: 		mod_s.saved.cur_fd = 0;
812: 		while (mod_s.saved.cur_fd != -1)
813: 		{
814: 			if (isConnectPending(mod_s.saved.cur_fd))
815: 			{
816: 				Log(TRACE_MINIMUM, -1, "Socket %d is connecting, reducing timeout from %d, no of sockets %d\n",
817: 					mod_s.saved.cur_fd, timeout_ms, mod_s.saved.nfds);
818: 
819: 				/* Will this result in excessive CPU use if the TCP connect is taking a long time,
820: 				 * such as on a satellite link? We could use a backoff algorithm if it turns out to be true */
821: 				timeout_ms = 0;
822: 				break;
823: 			}
824: 			mod_s.saved.cur_fd = (mod_s.saved.cur_fd == mod_s.saved.nfds - 1) ? -1 : mod_s.saved.cur_fd + 1;
825: 		}
826: 
827: 		/* clear interrupt socket - make sure it is unset */
828: 		{
829: 			static char dbuf[1];
830: 			/*int irc = */recv(sockfd[0], dbuf, 1, 0);
831: 		}
832: 		/* Prevent performance issue by unlocking the socket_mutex while waiting for a ready socket. */
833: 		Paho_thread_unlock_mutex(mutex);
834: 		*rc = poll(mod_s.saved.fds_read, mod_s.saved.nfds, timeout_ms);
835: 		Paho_thread_lock_mutex(mutex);
836: 		if (*rc == SOCKET_ERROR)
837: 		{
838: 			Socket_error("poll", 0);
839: 			goto exit;
840: 		}
841: 		Log(TRACE_MAX, -1, "Return code %d from poll", *rc);
842: 
843: 		/* check interrupt socket to see if we were interrupted */
844: 		{
845: 			static char dbuf[1];
846: 			int irc = recv(sockfd[0], dbuf, 1, 0);
847: 			if (irc > 0)
848: 			{
849: 				*interrupted = 1;
850: 				Log(TRACE_MINIMUM, -1, "Poll was interrupted, rc %d", irc);
851: 			}
852: 		}
853: 
854: 		if (rc1 == 0 && *rc == 0)
855: 		{
856: 			sock = 0;
857: 			goto exit; /* no work to do */
858: 		}
859: 
860: 		mod_s.saved.cur_fd = 0;
861: 		while (mod_s.saved.cur_fd != -1)
862: 		{
863: 			if (isReady(mod_s.saved.cur_fd))
864: 				break;
865: 			mod_s.saved.cur_fd = (mod_s.saved.cur_fd == mod_s.saved.nfds - 1) ? -1 : mod_s.saved.cur_fd + 1;
866: 		}
867: 	}
868: 
869: 	*rc = 0;
870: 	if (mod_s.saved.cur_fd == -1)
871: 		sock = 0;
872: 	else
873: 	{
874: 		sock = mod_s.saved.fds_read[mod_s.saved.cur_fd].fd;
875: 		mod_s.saved.cur_fd = (mod_s.saved.cur_fd == mod_s.saved.nfds - 1) ? -1 : mod_s.saved.cur_fd + 1;
876: 	}
877: exit:
878: 	Paho_thread_unlock_mutex(mutex);
879: 	FUNC_EXIT_RC(sock);
880: 	return sock;
881: } /* end getReadySocket */
882: #endif
