885: /**
886:  *  Reads one byte from a socket
887:  *  @param socket the socket to read from
888:  *  @param c the character read, returned
889:  *  @return completion code
890:  */
891: int Socket_getch(SOCKET socket, char* c)
892: {
893: 	int rc = SOCKET_ERROR;
894: 
895: 	FUNC_ENTRY;
896: 	if ((rc = SocketBuffer_getQueuedChar(socket, c)) != SOCKETBUFFER_INTERRUPTED)
897: 		goto exit;
898: 
899: 	if ((rc = recv(socket, c, (size_t)1, 0)) == SOCKET_ERROR)
900: 	{
901: 		int err = Socket_error("recv - getch", socket);
902: 		if (err == EWOULDBLOCK || err == EAGAIN)
903: 		{
904: 			rc = TCPSOCKET_INTERRUPTED;
905: 			SocketBuffer_interrupted(socket, 0);
906: 		}
907: 	}
908: 	else if (rc == 0)
909: 		rc = SOCKET_ERROR; 	/* The return value from recv is 0 when the peer has performed an orderly shutdown. */
910: 	else if (rc == 1)
911: 	{
912: 		SocketBuffer_queueChar(socket, *c);
913: 		rc = TCPSOCKET_COMPLETE;
914: 	}
915: exit:
916: 	FUNC_EXIT_RC(rc);
917: 	return rc;
918: }
