921: /**
922:  *  Attempts to read a number of bytes from a socket, non-blocking. If a previous read did not
923:  *  finish, then retrieve that data.
924:  *  @param socket the socket to read from
925:  *  @param bytes the number of bytes to read
926:  *  @param actual_len the actual number of bytes read
927:  *  @return completion code
928:  */
929: char *Socket_getdata(SOCKET socket, size_t bytes, size_t* actual_len, int *rc)
930: {
931: 	char* buf;
932: 
933: 	FUNC_ENTRY;
934: 	if (bytes == 0)
935: 	{
936: 		buf = SocketBuffer_complete(socket);
937: 		goto exit;
938: 	}
939: 
940: 	buf = SocketBuffer_getQueuedData(socket, bytes, actual_len);
941: 
942: 	if ((*rc = recv(socket, buf + (*actual_len), (int)(bytes - (*actual_len)), 0)) == SOCKET_ERROR)
943: 	{
944: 		*rc = Socket_error("recv - getdata", socket);
945: 		if (*rc != EAGAIN && *rc != EWOULDBLOCK)
946: 		{
947: 			buf = NULL;
948: 			goto exit;
949: 		}
950: 	}
951: 	else if (*rc == 0) /* rc 0 means the other end closed the socket, albeit "gracefully" */
952: 	{
953: 		buf = NULL;
954: 		goto exit;
955: 	}
956: 	else
957: 		*actual_len += *rc;
958: 
959: 	if (*actual_len == bytes)
960: 		SocketBuffer_complete(socket);
961: 	else /* we didn't read the whole packet */
962: 	{
963: 		SocketBuffer_interrupted(socket, *actual_len);
964: 		Log(TRACE_MAX, -1, "%d bytes expected but %d bytes now received", (int)bytes, (int)*actual_len);
965: 	}
966: exit:
967: 	FUNC_EXIT;
968: 	return buf;
969: }
