983: /**
984:  *  Attempts to write a series of iovec buffers to a socket in *one* system call so that
985:  *  they are sent as one packet.
986:  *  @param socket the socket to write to
987:  *  @param iovecs an array of buffers to write
988:  *  @param count number of buffers in iovecs
989:  *  @param bytes number of bytes actually written returned
990:  *  @return completion code, especially TCPSOCKET_INTERRUPTED
991:  */
992: int Socket_writev(SOCKET socket, iobuf* iovecs, int count, unsigned long* bytes)
993: {
994: 	int rc;
995: 
996: 	FUNC_ENTRY;
997: 	*bytes = 0L;
998: #if defined(_WIN32)
999: 	rc = WSASend(socket, iovecs, count, (LPDWORD)bytes, 0, NULL, NULL);
1000: 	if (rc == SOCKET_ERROR)
1001: 	{
1002: 		int err = Socket_error("WSASend - putdatas", socket);
1003: 		if (err == EWOULDBLOCK || err == EAGAIN)
1004: 			rc = TCPSOCKET_INTERRUPTED;
1005: 	}
1006: #else
1007: /*#define TCPSOCKET_INTERRUPTED_TESTING
1008: This section forces the occasional return of TCPSOCKET_INTERRUPTED,
1009: for testing purposes only!
1010: */
1011: #if defined(TCPSOCKET_INTERRUPTED_TESTING)
1012:   static int i = 0;
1013: 	if (++i >= 10 && i < 21)
1014: 	{
1015: 		if (1)
1016: 		{
1017: 		  printf("Deliberately simulating TCPSOCKET_INTERRUPTED\n");
1018: 		  rc = TCPSOCKET_INTERRUPTED; /* simulate a network wait */
1019: 	  }
1020: 		else
1021: 		{
1022: 			printf("Deliberately simulating SOCKET_ERROR\n");
1023: 		  rc = SOCKET_ERROR;
1024: 		}
1025: 		/* should *bytes always be 0? */
1026: 		if (i == 20)
1027: 		{
1028: 		  printf("Shutdown socket\n");
1029: 		  shutdown(socket, SHUT_WR);
1030: 	  }
1031: 	}
1032: 	else
1033: 	{
1034: #endif
1035: 	rc = writev(socket, iovecs, count);
