1037: 	{
1038: 		int err = Socket_error("writev - putdatas", socket);
1039: 		if (err == EWOULDBLOCK || err == EAGAIN)
1040: 			rc = TCPSOCKET_INTERRUPTED;
1041: 	}
1042: 	else
1043: 		*bytes = rc;
1044: #if defined(TCPSOCKET_INTERRUPTED_TESTING)
