1053: /**
1054:  *  Attempts to write a series of buffers to a socket in *one* system call so that they are
1055:  *  sent as one packet.
1056:  *  @param socket the socket to write to
1057:  *  @param buf0 the first buffer
1058:  *  @param buf0len the length of data in the first buffer
1059:  *  @param count number of buffers
1060:  *  @param buffers an array of buffers to write
1061:  *  @param buflens an array of corresponding buffer lengths
1062:  *  @return completion code, especially TCPSOCKET_INTERRUPTED
1063:  */
1064: int Socket_putdatas(SOCKET socket, char* buf0, size_t buf0len, PacketBuffers bufs)
1065: {
1066: 	unsigned long bytes = 0L;
1067: 	iobuf iovecs[5];
1068: 	int frees1[5];
1069: 	int rc = TCPSOCKET_INTERRUPTED, i;
1070: 	size_t total = buf0len;
1071: 
1072: 	FUNC_ENTRY;
1073: 	if (!Socket_noPendingWrites(socket))
1074: 	{
1075: 		Log(LOG_SEVERE, -1, "Trying to write to socket %d for which there is already pending output", socket);
1076: 		rc = SOCKET_ERROR;
1077: 		goto exit;
1078: 	}
1079: 
1080: 	for (i = 0; i < bufs.count; i++)
1081: 		total += bufs.buflens[i];
1082: 
1083: 	iovecs[0].iov_base = buf0;
1084: 	iovecs[0].iov_len = (ULONG)buf0len;
1085: 	frees1[0] = 1; /* this buffer should be freed by SocketBuffer if the write is interrupted */
1086: 	for (i = 0; i < bufs.count; i++)
1087: 	{
1088: 		iovecs[i+1].iov_base = bufs.buffers[i];
1089: 		iovecs[i+1].iov_len = (ULONG)bufs.buflens[i];
1090: 		frees1[i+1] = bufs.frees[i];
1091: 	}
1092: 
1093: 	if ((rc = Socket_writev(socket, iovecs, bufs.count+1, &bytes)) != SOCKET_ERROR)
1094: 	{
1095: 		if (bytes == total)
1096: 			rc = TCPSOCKET_COMPLETE;
1097: 		else
1098: 		{
1099: 			SOCKET* sockmem = (SOCKET*)malloc(sizeof(SOCKET));
1100: 
1101: 			if (!sockmem)
1102: 			{
1103: 				rc = PAHO_MEMORY_ERROR;
1104: 				goto exit;
1105: 			}
1106: 			Log(TRACE_MIN, -1, "Partial write: %lu bytes of %lu actually written on socket %d",
1107: 					bytes, total, socket);
1108: #if defined(OPENSSL)
1109: 			SocketBuffer_pendingWrite(socket, NULL, bufs.count+1, iovecs, frees1, total, bytes);
1110: #else
1111: 			SocketBuffer_pendingWrite(socket, bufs.count+1, iovecs, frees1, total, bytes);
1112: #endif
1113: 			*sockmem = socket;
1114: 			if (!ListAppend(mod_s.write_pending, sockmem, sizeof(int)))
1115: 			{
1116: 				free(sockmem);
1117: 				rc = PAHO_MEMORY_ERROR;
1118: 				goto exit;
1119: 			}
1120: #if defined(USE_SELECT)
1121: 			FD_SET(socket, &(mod_s.pending_wset));
1122: #endif
1123: 			rc = TCPSOCKET_INTERRUPTED;
1124: 		}
1125: 	}
1126: exit:
1127: 	FUNC_EXIT_RC(rc);
1128: 	return rc;
1129: }
