1159: /**
1160:  *  Close a socket without removing it from the select list.
1161:  *  @param socket the socket to close
1162:  *  @return completion code
1163:  */
1164: int Socket_close_only(SOCKET socket)
1165: {
1166: 	int rc;
1167: 
1168: 	FUNC_ENTRY;
1169: 	Socket_interrupt();
1170: #if defined(_WIN32)
1171: 	if (shutdown(socket, SD_BOTH) == SOCKET_ERROR)
1172: 		Socket_error("shutdown", socket);
1173: 	if ((rc = closesocket(socket)) == SOCKET_ERROR)
1174: 		Socket_error("close", socket);
1175: #else
1176: 	if (shutdown(socket, SHUT_WR) == SOCKET_ERROR)
1177: 		Socket_error("shutdown", socket);
1178: 	if ((rc = recv(socket, NULL, (size_t)0, 0)) == SOCKET_ERROR)
1179: 		Socket_error("shutdown", socket);
