1617: /**
1618:  *  Continue an outstanding write for a particular socket
1619:  *  @param socket that socket
1620:  *  @return completion code: 0=incomplete, 1=complete, -1=socket error
1621:  */
1622: int Socket_continueWrite(SOCKET socket)
1623: {
1624: 	int rc = 0;
1625: 	pending_writes* pw;
1626: 	unsigned long curbuflen = 0L, /* cumulative total of buffer lengths */
1627: 		bytes = 0L;
1628: 	int curbuf = -1, i;
1629: 	iobuf iovecs1[5];
1630: 
1631: 	FUNC_ENTRY;
1632: 	pw = SocketBuffer_getWrite(socket);
1633: 
1634: #if defined(OPENSSL)
1635: 	if (pw->ssl)
1636: 	{
1637: 		rc = SSLSocket_continueWrite(pw);
1638: 		goto exit;
1639: 	}
1640: #endif
1641: 
1642: 	for (i = 0; i < pw->count; ++i)
1643: 	{
1644: 		if (pw->bytes <= curbuflen)
1645: 		{ /* if previously written length is less than the buffer we are currently looking at,
1646: 				add the whole buffer */
1647: 			iovecs1[++curbuf].iov_len = pw->iovecs[i].iov_len;
1648: 			iovecs1[curbuf].iov_base = pw->iovecs[i].iov_base;
1649: 		}
1650: 		else if (pw->bytes < curbuflen + pw->iovecs[i].iov_len)
1651: 		{ /* if previously written length is in the middle of the buffer we are currently looking at,
1652: 				add some of the buffer */
1653: 			size_t offset = pw->bytes - curbuflen;
1654: 			iovecs1[++curbuf].iov_len = pw->iovecs[i].iov_len - (ULONG)offset;
1655: 			iovecs1[curbuf].iov_base = (char*)pw->iovecs[i].iov_base + offset;
1656: 		}
1657: 		curbuflen += pw->iovecs[i].iov_len;
1658: 	}
1659: 
1660: 	if ((rc = Socket_writev(socket, iovecs1, curbuf+1, &bytes)) != SOCKET_ERROR)
1661: 	{
1662: 		pw->bytes += bytes;
1663: 		if ((rc = (pw->bytes == pw->total)))
1664: 		{  /* topic and payload buffers are freed elsewhere, when all references to them have been removed */
1665: 			for (i = 0; i < pw->count; i++)
1666: 			{
1667: 				if (pw->frees[i])
1668:                 {
1669: 					free(pw->iovecs[i].iov_base);
1670:                     pw->iovecs[i].iov_base = NULL;
1671:                 }
1672: 			}
1673: 			rc = 1; /* signal complete */
1674: 			Log(TRACE_MIN, -1, "ContinueWrite: partial write now complete for socket %d", socket);
1675: 		}
1676: 		else
1677: 		{
1678: 			rc = 0; /* signal not complete */
1679: 			Log(TRACE_MIN, -1, "ContinueWrite wrote +%lu bytes on socket %d", bytes, socket);
1680: 		}
1681: 	}
1682: 	else /* if we got SOCKET_ERROR we need to clean up anyway - a partial write is no good anymore */
1683: 	{
1684: 		for (i = 0; i < pw->count; i++)
1685: 		{
1686: 			if (pw->frees[i])
1687:             {
1688: 				free(pw->iovecs[i].iov_base);
1689:                 pw->iovecs[i].iov_base = NULL;
1690:             }
1691: 		}
1692: 	}
1693: #if defined(OPENSSL)
1694: exit:
1695: #endif
1696: 	FUNC_EXIT_RC(rc);
1697: 	return rc;
1698: }
