162: /**
163:  * Check the dest parameter against the no_proxy blacklist
164:  *
165:  * no_proxy:
166:  *  1. Use lowercase form.
167:  *  2. Use comma-separated hostname:port values.
168:  *  3. IP addresses are okay, but hostnames are never resolved.
169:  *  4. Suffixes are always matched (e.g. example.com will match test.example.com).
170:  *  5. If top-level domains need to be matched, leading dots are accepted e.g. .com
171:  *
172:  * @param dest the destination hostname/ip address
173:  * @param no_proxy the no_proxy list, probably from the environment
174:  * @return 1 - use the proxy, 0 - don't use the proxy
175:  */
176: int Proxy_noProxy(const char* dest, char* no_proxy)
177: {
178: 	char* saveptr = NULL;
179: 	char* curtok = NULL;
180: 	int port = 0;
181: 	int destport = 0;
182: 	int port_matches = 0;
183: 	size_t hostlen = 0;
184: 	size_t desthostlen = 0;
185: 	int rc = 1;
186: 	char* no_proxy_list = NULL;
187: 
188: 	if ((no_proxy_list = MQTTStrdup(no_proxy)) == NULL)
189: 	{
190: 		rc = PAHO_MEMORY_ERROR;
191: 		goto exit;
192: 	}
193: 
194: 	curtok = strtok_r(no_proxy_list, ",", &saveptr);
195: 	while (curtok)
196: 	{
197: 		char* host = curtok;
198: 		int matched = 0;
199: 		int pos = 1;
200: 		const char* topic;
201: 
202: 		if (curtok == NULL)
203: 			break;
204: 		if (host[0] == '.')
205: 			host++;
206: 
207: 		hostlen = MQTTProtocol_addressPort(host, &port, &topic, -99);
208: 
209: 		desthostlen = MQTTProtocol_addressPort(dest, &destport, &topic, -99);
210: 		if (dest[desthostlen] == '/')
211: 			desthostlen--;
212: 
213: 		/* check if port matches */
214: 		if (port == -99)
215: 			port_matches = 1; /* no_proxy port absence matches any */
216: 		else if (destport != -99)
217: 		{
218: 			if (destport == port)
219: 				port_matches = 1;
220: 		}
221: 		if (memcmp(host, "*", 1) == 0) /* * matches anything */
222: 		{
223: 			/* match any host or address */
224: 			if (port_matches == 1)
225: 			{
226: 				rc = 0;
227: 				break;
228: 			}
229: 		}
230: 		/* now see if .host matches the end of the dest string */
231: 		/* match backwards from the end */
232: 		while (host[hostlen - pos] == dest[desthostlen - pos])
233: 		{
234: 			if (pos == hostlen) /* reached the beginning of the no_proxy definition */
235: 			{
236: 				if ((pos == desthostlen || dest[desthostlen - pos - 1] == '.') && port_matches)
237: 					matched = 1;
238: 				break;
239: 			}
240: 			else if (pos == desthostlen) /* reached the beginning of the destination string */
241: 				break;
242: 			pos++;
243: 		}
244: 		if (matched)
245: 		{
246: 			rc = 0;
247: 			break;
248: 		}
249: 		curtok = strtok_r(NULL, ",", &saveptr);
250: 	}
251: 	if (rc == 0)
252: 		Log(TRACE_PROTOCOL, -1, "Matched destination %s against no_proxy %s. Don't use proxy.", dest, curtok);
253: 	free(no_proxy_list);
254: exit:
255: 	return rc;
256: }
