259: /**
260:  * Allow user or password characters to be expressed in the form of %XX, XX being the
261:  * hexadecimal value of the character. This will avoid problems when a user code or a password
262:  * contains a '@' or another special character ('%' included)
263:  * @param p0 output string
264:  * @param p1 input string
265:  * @param basic_auth_in_len
266:  */
267: void Proxy_specialChars(char* p0, char* p1, b64_size_t *basic_auth_in_len)
268: {
269: 	while (*p1 != '@')
270: 	{
271: 		if (*p1 != '%')
272: 		{
273: 			*p0++ = *p1++;
274: 		}
275: 		else if (isxdigit((unsigned char)*(p1 + 1)) && isxdigit((unsigned char)*(p1 + 2)))
276: 		{
277: 			/* next 2 characters are hexa digits */
278: 			char hex[3];
279: 			p1++;
280: 			hex[0] = *p1++;
281: 			hex[1] = *p1++;
282: 			hex[2] = '\0';
283: 			*p0++ = (char)strtol(hex, 0, 16);
284: 			/* 3 input char => 1 output char */
285: 			*basic_auth_in_len -= 2;
286: 		}
287: 	}
288: 	*p0 = 0x0;
289: }
