292: /**
293:  * Set the HTTP proxy for connecting
294:  * Examples of proxy settings:
295:  *   http://your.proxy.server:8080/
296:  *   http://user:pass@my.proxy.server:8080/
297:  *
298:  * @param aClient pointer to Clients object
299:  * @param source the proxy setting from environment or API
300:  * @param [out] dest pointer to output proxy info
301:  * @param [out] auth_dest pointer to output authentication material
302:  * @param prefix expected URI prefix: http:// or https://
303:  * @return 0 on success, non-zero otherwise
304:  */
305: int Proxy_setHTTPProxy(Clients* aClient, char* source, char** dest, char** auth_dest, char* prefix)
306: {
307: 	b64_size_t basic_auth_in_len, basic_auth_out_len;
308: 	b64_data_t *basic_auth;
309: 	char *p1;
310: 	int rc = 0;
311: 
312: 	if (*auth_dest)
313: 	{
314: 		free(*auth_dest);
315: 		*auth_dest = NULL;
316: 	}
317: 
318: 	if (source)
319: 	{
320: 		if ((p1 = strstr(source, prefix)) != NULL) /* skip http:// prefix, if any */
321: 			source += strlen(prefix);
322: 		*dest = source;
323: 		if ((p1 = strchr(source, '@')) != NULL) /* find user.pass separator */
324: 			*dest = p1 + 1;
325: 
326: 		if (p1)
327: 		{
328: 			/* basic auth len is string between http:// and @ */
329: 			basic_auth_in_len = (b64_size_t)(p1 - source);
330: 			if (basic_auth_in_len > 0)
331: 			{
332: 				basic_auth = (b64_data_t *)malloc(sizeof(char)*(basic_auth_in_len+1));
333: 				if (!basic_auth)
334: 				{
335: 					rc = PAHO_MEMORY_ERROR;
336: 					goto exit;
337: 				}
338: 				Proxy_specialChars((char*)basic_auth, source, &basic_auth_in_len);
339: 				basic_auth_out_len = Base64_encodeLength(basic_auth, basic_auth_in_len) + 1; /* add 1 for trailing NULL */
340: 				if ((*auth_dest = (char *)malloc(sizeof(char)*basic_auth_out_len)) == NULL)
341: 				{
342: 					free(basic_auth);
343: 					rc = PAHO_MEMORY_ERROR;
344: 					goto exit;
345: 				}
346: 				Base64_encode(*auth_dest, basic_auth_out_len, basic_auth, basic_auth_in_len);
347: 				free(basic_auth);
348: 			}
349: 		}
350: 	}
351: exit:
352: 	return rc;
